package org.opengridseg.export;
public final class ExportBar { private final String id;private final int arrayId,row,col;private final String status;private final double originalX,originalY,rotatedX,rotatedY;private final boolean boundaryUncertain; public ExportBar(String id,int arrayId,int row,int col,String status,double originalX,double originalY,double rotatedX,double rotatedY,boolean boundaryUncertain){this.id=id;this.arrayId=arrayId;this.row=row;this.col=col;this.status=status;this.originalX=originalX;this.originalY=originalY;this.rotatedX=rotatedX;this.rotatedY=rotatedY;this.boundaryUncertain=boundaryUncertain;} public String id(){return id;}public int arrayId(){return arrayId;}public int row(){return row;}public int col(){return col;}public String status(){return status;}public double originalX(){return originalX;}public double originalY(){return originalY;}public double rotatedX(){return rotatedX;}public double rotatedY(){return rotatedY;}public boolean boundaryUncertain(){return boundaryUncertain;} }
